<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';require_role(['admin']);
$id=max(0,(int)($_GET['id']??0));$q=db()->prepare('SELECT * FROM personnel WHERE id=?');$q->execute([$id]);$person=$q->fetch();if(!$person){flash('danger','پرسنل پیدا نشد.');redirect('personnel.php');}
$types=['computer'=>'کامپیوتر','printer'=>'چاپگر','display'=>'نمایشگر','scanner'=>'اسکنر'];$q=db()->prepare('SELECT asset_no,asset_type,hostname,manufacturer,model,serial_no,location,status FROM assets WHERE personnel_id=? ORDER BY asset_type,asset_no');$q->execute([$id]);$assets=$q->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تجهیزات <?=e($person['full_name'])?></title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="personnel.php">پرسنل</a><a href="assets.php">تجهیزات</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><h1>تجهیزات شخصی: <?=e($person['full_name'])?></h1><p class="muted">کدملی: <?=e($person['national_id']??'—')?> — تلفن همراه: <?=e($person['mobile']??'—')?></p></div><a class="btn" href="personnel.php">بازگشت به پرسنل</a></div><section class="cards mini-cards"><?php foreach($types as $k=>$label):?><div class="stat-card"><span><?=e($label)?></span><b><?=count(array_filter($assets,fn($a)=>$a['asset_type']===$k))?></b></div><?php endforeach;?></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>شماره اموال</th><th>نوع</th><th>نام دستگاه</th><th>برند/مدل</th><th>سریال</th><th>مکان</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($assets as $a):?><tr><td><strong><?=e($a['asset_no'])?></strong></td><td><?=e($types[$a['asset_type']]??$a['asset_type'])?></td><td><?=e($a['hostname']?:'—')?></td><td><?=e(trim(($a['manufacturer']??'').' '.($a['model']??''))?:'—')?></td><td><?=e($a['serial_no']?:'—')?></td><td><?=e($a['location']?:'—')?></td><td><span class="badge <?=e($a['status'])?>"><?=e(['active'=>'فعال','repair'=>'تعمیر','retired'=>'اسقاط','lost'=>'مفقود'][$a['status']]??$a['status'])?></span></td><td><a class="btn small" href="asset_view.php?asset_no=<?=urlencode($a['asset_no'])?>">مشاهده</a></td></tr><?php endforeach;?><?php if(!$assets):?><tr><td colspan="8" class="empty">تجهیزی برای این فرد ثبت نشده است.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
